Thanks for the plugin suggestion. The code you've given works for incoming request validation but not for the serialize step, and it doesn't solve the reuse scenario (either directly or through $refs) across different routes, which is the main problem I'd hoped to solve.

Is it preferable that more nuanced AJV control is in a separate plugin as far as the fastify ecosystem goes? I'd mostly hoped to reuse the existing AJV instance inside fastify, but if that's a better approach I'd be happy to chase that down.

Sorry for the delay.

Can we this adding only a `setSerializer` fastify method and writing a plugin like this:

```
const Ajv = require('ajv')
const fp = require('fastify-plugin')

module.exports = fp(function (fastify, options, next) {
  const ajvInstance = new Ajv(options.ajvOptions)

  const schemas = {}
  fastify.decorate('addSchema', function addSchema (schema) {
    ajvInstance.addSchema(schema)
    schemas[schema.$id] = schema
  })
  fastify.decorate('addKeyword', function addKeyword (name, def) {
    ajvInstance.addSchema(name, def)
    schemas[name] = def
  })

  fastify.setSchemaCompiler(function (schema, body) {
    return ajvInstance.compile(schema, body)
  })

  fastify.setSerializer(function (schema) { // TODO
    return fastJson(schema, { schema: schemas }) // or something like that
  })

  next()
})
```

